/* Real Gregorian calendar, local-time seasons and seasonal simulated weather. */
(()=>{'use strict';
const weathers=['clear','rain','sleet','snow','thunderstorm','snowstorm','blizzard'];
const seasons=['spring','summer','autumn','winter'];
function validZone(z){try{new Intl.DateTimeFormat('en-US',{timeZone:z}).format();return true}catch{return false}}
function ensure(s){if(!s.cityAtmosphere||typeof s.cityAtmosphere!=='object'||Array.isArray(s.cityAtmosphere))s.cityAtmosphere={};const a=s.cityAtmosphere;a.clock='real';if(typeof a.timeZone!=='string'||!validZone(a.timeZone))a.timeZone='America/Chicago';if(!['north','south'].includes(a.hemisphere))a.hemisphere='north';if(!['seasonal','manual'].includes(a.weatherMode))a.weatherMode='seasonal';if(!weathers.includes(a.weather))a.weather='clear';if(!['real','manual'].includes(a.seasonMode))a.seasonMode='real';if(!seasons.includes(a.season))a.season='autumn';if(typeof a.sound!=='boolean')a.sound=false;for(const key of ['musicVolume','effectsVolume'])if(!Number.isFinite(a[key])||a[key]<0||a[key]>1)a[key]=key==='musicVolume'?.28:.35;return a}
function clock(date,zone){const parts=new Intl.DateTimeFormat('en-US',{timeZone:zone,year:'numeric',month:'numeric',day:'numeric',hour:'numeric',minute:'numeric',second:'numeric',hourCycle:'h23'}).formatToParts(date),p=Object.fromEntries(parts.filter(v=>v.type!=='literal').map(v=>[v.type,Number(v.value)]));const day=Date.UTC(p.year,p.month-1,p.day)/86400000+1;return{...p,ordinal:day,key:p.year+'-'+String(p.month).padStart(2,'0')+'-'+String(p.day).padStart(2,'0'),minutes:p.hour*60+p.minute}}
function season(c,hemisphere='north'){const n=Math.floor(c.month%12/3);return(hemisphere==='south'?['summer','autumn','winter','spring']:['winter','spring','summer','autumn'])[n]}
function conditions(s,date=new Date()){const a=ensure(s),c=clock(date,a.timeZone),se=a.seasonMode==='manual'?a.season:season(c,a.hemisphere);let weather=a.weather;if(a.weatherMode==='seasonal'){const tables={spring:['clear','rain','rain','clear','thunderstorm','clear','sleet','clear'],summer:['clear','clear','thunderstorm','clear','rain','clear','clear','clear'],autumn:['clear','rain','clear','sleet','rain','clear','thunderstorm','clear'],winter:['snow','clear','sleet','snow','snowstorm','clear','blizzard','rain']};const slot=Math.floor(c.hour/3);weather=tables[se][((c.ordinal*5+slot*3)%8+8)%8]}const daylight={spring:[6,19],summer:[5,21],autumn:[7,18],winter:[8,17]}[se];return{...c,season:se,weather,night:c.hour<daylight[0]||c.hour>=daylight[1],timeZone:a.timeZone}}
function monthGrid(year,month){const first=new Date(Date.UTC(year,month,1)),y=first.getUTCFullYear(),m=first.getUTCMonth(),offset=first.getUTCDay(),days=new Date(Date.UTC(y,m+1,0)).getUTCDate();return{year:y,month:m,offset,days,cells:Array.from({length:Math.ceil((offset+days)/7)*7},(_,i)=>i>=offset&&i<offset+days?i-offset+1:null)}}
globalThis.EldoriaAtmosphereModel={weathers,seasons,validZone,ensure,clock,season,conditions,monthGrid};
})();
